-- pos-shop-manager: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.appointment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    is_conflict_override boolean NOT NULL,
    reopen_flag boolean NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    end_at timestamp(6) with time zone NOT NULL,
    start_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    crm_customer_id uuid NOT NULL,
    crm_vehicle_id uuid NOT NULL,
    location_id uuid NOT NULL,
    source_type character varying(32),
    status character varying(32) NOT NULL,
    assignment_status character varying(64),
    resource_type character varying(64),
    cancellation_reason character varying(128),
    idempotency_key character varying(128),
    resource_id character varying(128),
    source_id character varying(128),
    cancellation_notes character varying(1000),
    created_by character varying(255),
    customer_snapshot text,
    vehicle_snapshot text,
    workorder_link_ref character varying(255),
    CONSTRAINT appointment_cancellation_reason_check CHECK (((cancellation_reason)::text = ANY (ARRAY[('CUSTOMER_REQUEST'::character varying)::text, ('TECHNICIAN_UNAVAILABLE'::character varying)::text, ('WEATHER'::character varying)::text, ('VEHICLE_NOT_READY'::character varying)::text, ('OTHER'::character varying)::text]))),
    CONSTRAINT appointment_source_type_check CHECK (((source_type)::text = ANY (ARRAY[('ESTIMATE'::character varying)::text, ('WORK_ORDER'::character varying)::text]))),
    CONSTRAINT appointment_status_check CHECK (((status)::text = ANY (ARRAY[('SCHEDULED'::character varying)::text, ('CHECKED_IN'::character varying)::text, ('WORK_IN_PROGRESS'::character varying)::text, ('WAITING_FOR_PARTS'::character varying)::text, ('QUALITY_CHECK'::character varying)::text, ('READY_FOR_PICKUP'::character varying)::text, ('COMPLETED'::character varying)::text, ('CANCELLED'::character varying)::text, ('INVOICED'::character varying)::text, ('REOPENED'::character varying)::text])))
);

CREATE TABLE public.appointment_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    new_end_at timestamp(6) with time zone,
    new_start_at timestamp(6) with time zone,
    previous_end_at timestamp(6) with time zone,
    previous_start_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    audit_id uuid NOT NULL,
    action character varying(32) NOT NULL,
    cancellation_reason character varying(128),
    actor_id character varying(255) NOT NULL,
    CONSTRAINT appointment_audit_action_check CHECK (((action)::text = ANY (ARRAY[('RESCHEDULED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.appointment_service_request (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    service_entity_id uuid NOT NULL,
    service_request_id uuid NOT NULL
);

CREATE TABLE public.appointment_status_timeline (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    change_timestamp timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    source_event_id uuid NOT NULL,
    status character varying(50) NOT NULL,
    CONSTRAINT appointment_status_timeline_status_check CHECK (((status)::text = ANY (ARRAY[('SCHEDULED'::character varying)::text, ('CHECKED_IN'::character varying)::text, ('WORK_IN_PROGRESS'::character varying)::text, ('WAITING_FOR_PARTS'::character varying)::text, ('QUALITY_CHECK'::character varying)::text, ('READY_FOR_PICKUP'::character varying)::text, ('COMPLETED'::character varying)::text, ('CANCELLED'::character varying)::text, ('INVOICED'::character varying)::text, ('REOPENED'::character varying)::text])))
);

CREATE TABLE public.assignment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    is_override boolean NOT NULL,
    version integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    assignment_id uuid NOT NULL,
    resource_id uuid,
    status character varying(20) NOT NULL,
    resource_type character varying(50),
    notes character varying(500),
    override_reason character varying(2000),
    CONSTRAINT assignment_status_check CHECK (((status)::text = ANY (ARRAY[('CONFIRMED'::character varying)::text, ('IN_PROGRESS'::character varying)::text, ('COMPLETED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.assignment_mechanic (
