CREATE TABLE public.reschedule_history (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    conflict_overridden boolean NOT NULL,
    notify_customer boolean NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    new_end_at timestamp(6) with time zone NOT NULL,
    new_start_at timestamp(6) with time zone NOT NULL,
    previous_end_at timestamp(6) with time zone NOT NULL,
    previous_start_at timestamp(6) with time zone NOT NULL,
    rescheduled_at timestamp(6) with time zone NOT NULL,
    appointment_id uuid NOT NULL,
    reschedule_id uuid NOT NULL,
    assignment_status character varying(50),
    notification_status character varying(50),
    reschedule_reason character varying(50) NOT NULL,
    reschedule_reason_notes character varying(1000),
    rescheduled_by character varying(255) NOT NULL,
    CONSTRAINT reschedule_history_reschedule_reason_check CHECK (((reschedule_reason)::text = ANY (ARRAY[('CUSTOMER_REQUEST'::character varying)::text, ('SHOP_CAPACITY'::character varying)::text, ('EQUIPMENT_ISSUE'::character varying)::text, ('MECHANIC_UNAVAILABLE'::character varying)::text, ('PARTS_DELAY'::character varying)::text, ('WEATHER'::character varying)::text, ('EMERGENCY'::character varying)::text, ('MANAGER_DISCRETION'::character varying)::text, ('OTHER'::character varying)::text])))
