    reason_notes character varying(2048),
    actor_user_id character varying(255) NOT NULL,
    change_patch text,
    CONSTRAINT shop_audit_entry_event_type_check CHECK (((event_type)::text = ANY (ARRAY[('SCHEDULE_CREATED'::character varying)::text, ('SCHEDULE_UPDATED'::character varying)::text, ('SCHEDULE_CANCELLED'::character varying)::text, ('ASSIGNMENT_CREATED'::character varying)::text, ('ASSIGNMENT_REMOVED'::character varying)::text])))
